cd /Users/b612-lp/bench-workspaces/r1028/dsh/bird-ca-schools-15__r3 && sqlite3 -header -column inputs/db/california_schools.sqlite <<'SQL'
select District, FundingType, count(*) from schools group by 1,2 order by 3 desc limit 15;
select '--- Q62 variants';
select sum(case when `Free Meal Count (K-12)`*100/`Enrollment (K-12)` < 0.18 then 1 else 0 end) as pct018,
sum(case when `Free Meal Count (K-12)`/`Enrollment (K-12)` < 0.18 then 1 else 0 end) as frac018,
sum(case when `Free Meal Count (K-12)`*100/`Enrollment (K-12)` < 18 then 1 else 0 end) as pct18
from frpm f join schools s on f.CDSCode=s.CDSCode where s.County='Los Angeles' and s.Charter=0;
select '--- magnet K8 variants';
select count(*) from frpm f join schools s on f.CDSCode=s.CDSCode where s.Magnet=1 and f.`Low Grade`='K' and f.`High Grade`='8';
select count(*) from frpm f join schools s on f.CDSCode=s.CDSCode where s.Magnet=1 and s.GSoffered='K-8';
select '--- sample low/high';
select distinct `Low Grade`, `High Grade` from frpm where `High Grade`='8' limit 20;
SQL

cd /Users/b612-lp/bench-workspaces/r1028/dsh/bird-ca-schools-15__r3 && sqlite3 -header -column inputs/db/california_schools.sqlite <<'SQL'
select count(*) as n, max(cast(NumGE1500 as real)/NumTstTakr) as maxrate, max(AvgScrWrite) from satscores;
select count(*) from satscores where cast(NumGE1500 as real)/NumTstTakr > 0.3;
select cds,sname,NumTstTakr,NumGE1500, cast(NumGE1500 as real)/NumTstTakr as r from satscores where NumTstTakr>0 order by r desc limit 5;
select '--- top numge1500';
select cds,sname,NumGE1500 from satscores order by NumGE1500 desc limit 5;
select '--- Q12 join count';
select count(*), max(T1.`Free Meal Count (Ages 5-17)` / T1.`Enrollment (Ages 5-17)`) from frpm T1 join satscores T2 on T1.CDSCode=T2.cds where cast(T2.NumGE1500 as real)/T2.NumTstTakr > 0.3;
select '--- Q12 no cast';
select count(*), max(T1.`Free Meal Count (Ages 5-17)` / T1.`Enrollment (Ages 5-17)`) from frpm T1 join satscores T2 on T1.CDSCode=T2.cds where T2.NumGE1500 / T2.NumTstTakr > 0.3;
select '--- check ratios values';
select NumGE1500, NumTstTakr, NumGE1500/NumTstTakr from satscores limit 5;
SQL

cd /Users/b612-lp/bench-workspaces/r1028/dsh/bird-ca-schools-15__r3 && sqlite3 -header -column inputs/db/california_schools.sqlite <<'SQL'
select t.cds,t.rtype,t.sname,t.NumGE1500,s.School,s.AdmFName1,s.AdmLName1,s.AdmFName2,s.AdmLName2,s.AdmFName3,s.AdmLName3
from satscores t join schools s on t.cds=s.CDSCode
order by t.NumGE1500 desc limit 10;
select '--- school rtype only top';
select t.cds,t.rtype,t.sname,t.NumGE1500,s.School,s.AdmFName1,s.AdmLName1
from satscores t join schools s on t.cds=s.CDSCode
where t.rtype='S' order by t.NumGE1500 desc limit 5;
select '--- Q36 gold variants';
select count(*) from satscores t join schools s on t.cds=s.CDSCode where s.DOC!='' and t.rtype='D';
select rtype,count(*) from satscores group by rtype;
SQL

cd /Users/b612-lp/bench-workspaces/r1028/dsh/bird-ca-schools-15__r3 && sqlite3 -header -column inputs/db/california_schools.sqlite <<'SQL'
select s.School, s.Charter, f.`Free Meal Count (K-12)`, f.`Enrollment (K-12)`, f.`Free Meal Count (K-12)`*100.0/f.`Enrollment (K-12)` pct
from frpm f join schools s on f.CDSCode=s.CDSCode
where s.County='Los Angeles' and s.Charter=0 and f.`Free Meal Count (K-12)`*100.0/f.`Enrollment (K-12)` < 0.18;
select '--- Q24 compare pct col vs calc';
select count(*) from frpm f join satscores t on f.CDSCode=t.cds where f.`Percent (%) Eligible Free (K-12)`>0.1 and t.NumGE1500>0;
select count(*) from frpm f join satscores t on f.CDSCode=t.cds where f.`Free Meal Count (K-12)`/f.`Enrollment (K-12)`>0.1 and t.NumGE1500>0;
select 'diff rows';
select f.CDSCode,f.`School Name`,f.`Free Meal Count (K-12)`/f.`Enrollment (K-12)` a,f.`Percent (%) Eligible Free (K-12)` b from frpm f join satscores t on f.CDSCode=t.cds where t.NumGE1500>0 and (f.`Free Meal Count (K-12)`/f.`Enrollment (K-12)`>0.1) <> (f.`Percent (%) Eligible Free (K-12)`>0.1);
select '--- Q25 dname variant';
select t.sname,f.`Charter Funding Type` from frpm f join satscores t on f.CDSCode=t.cds where t.dname like 'Riverside%' and t.AvgScrMath>400;
select '--- Q31 values';
select `School Name`, `Enrollment (K-12)`, `Free Meal Count (K-12)`, `Free Meal Count (K-12)`/`Enrollment (K-12)` r from frpm order by `Enrollment (K-12)` desc limit 13;
SQL

cd /Users/b612-lp/bench-workspaces/r1028/dsh/bird-ca-schools-15__r3 && sqlite3 -header -column inputs/db/california_schools.sqlite <<'SQL'
select
 sum(case when s.OpenDate > '1991-12-31' or s.ClosedDate < '2000-01-01' then 1 else 0 end) v1,
 sum(case when s.OpenDate >= '1991-01-01' or s.ClosedDate < '2000-01-01' then 1 else 0 end) v2,
 sum(case when s.OpenDate > '1991-01-01' or s.ClosedDate < '2000-01-01' then 1 else 0 end) v3,
 sum(case when s.OpenDate > '1991-12-31' or s.ClosedDate < '1999-12-31' then 1 else 0 end) v4,
 count(*) total
from schools s join satscores t on t.cds=s.CDSCode;
select 'dates near boundary';
select distinct OpenDate from schools where OpenDate between '1991-01-01' and '1992-01-01' order by 1;
select distinct ClosedDate from schools where ClosedDate between '1999-01-01' and '2001-01-01' order by 1;
SQL

cd /Users/b612-lp/bench-workspaces/r1028/dsh/bird-ca-schools-15__r3 && sqlite3 -header -column inputs/db/california_schools.sqlite <<'SQL'
select max(f.`Free Meal Count (Ages 5-17)`/f.`Enrollment (Ages 5-17)`) computed, max(f.`Percent (%) Eligible Free (Ages 5-17)`) col
from frpm f join satscores t on f.CDSCode=t.cds where cast(t.NumGE1500 as real)/t.NumTstTakr>0.3;
select f.CDSCode,f.`School Name`,f.`Free Meal Count (Ages 5-17)`/f.`Enrollment (Ages 5-17)` computed,f.`Percent (%) Eligible Free (Ages 5-17)` col,t.NumGE1500,t.NumTstTakr
from frpm f join satscores t on f.CDSCode=t.cds where cast(t.NumGE1500 as real)/t.NumTstTakr>0.3 order by computed desc limit 3;
SQL
